type Any = Record<string, any>;
type Model = Any & { id: string; name: string; filename: string; type: string; baseModel: string; path: string; size: number; triggerWords: string[]; tags: string[]; coverPath?: string; missing?: boolean };
type Snapshot = { planTemplates?: Any[]; generationChoices?: Any; baseRequirements: Any[]; downloadQueuePaused: boolean; removedModelCount: number; loraCategories: string[]; imageAlbums: Any[]; models: Model[]; recipes: Any[]; downloads: Any[]; settings: Any; plan: Any; automationOutputs: Any; runs: Any[]; connection: Any; workflowFiles: Any[]; preparingRun: boolean; scanning: boolean; keyError?: string; keyConfigured: boolean; dataDir: string; version: string };
declare global { interface Window { studio: { call: (method: string, payload?: any) => Promise<any>; onChange: (fn: () => void) => () => void } } }
const api = (method: string, payload?: any) => window.studio.call(method, payload);
const uid = () => crypto.randomUUID();
const bytes = (n = 0) => n >= 1024 ** 3 ? `${(n / 1024 ** 3).toFixed(2)} GB` : n >= 1024 ** 2 ? `${(n / 1024 ** 2).toFixed(1)} MB` : `${Math.round(n / 1024)} KB`;
const cover = (m: Model) => m.coverPath ? `cms-media://asset/${m.id}/cover?v=${m.coverRevision || m.modified || 0}` : '';
const typeLabel = (type: string) => ({ Checkpoint: 'Checkpoint', LORA: 'LoRA', LoCon: 'LoCon', DoRA: 'DoRA', TextualInversion: 'Embedding', Upscaler: '放大模型', Controlnet: 'ControlNet' }[type] || type);
const statusLabel: Any = { queued: '等待中', resolving: '获取下载地址', downloading: '下载中', verifying: '校验 SHA256', archiving: '保存资料', paused: '已暂停', canceled: '已取消', failed: '下载失败', partial: '封面待补全', complete: '已完成' };
const errorText = (error: any) => String(error?.message || error).replace(/^Error invoking remote method '[^']+': (Error: )?/, '');
const move = <T,>(array: T[], from: number, to: number): T[] => { const copy = [...array]; if (to < 0 || to >= copy.length || from < 0) return copy; const [item] = copy.splice(from, 1); copy.splice(to, 0, item); return copy; };

function Button({ children, icon: Icon, className = '', ...props }: any) { return <button className={`button ${className}`} {...props}>{Icon && <Icon size={16}/>}<span>{children}</span></button>; }
function IconButton({ icon: Icon, label, ...props }: any) { return <button className="icon-button" title={label} aria-label={label} {...props}><Icon size={17}/></button>; }
function Badge({ children, tone = '' }: any) { return <span className={`badge ${tone}`}>{children}</span>; }
function Cover({ model, className = '' }: { model: Model; className?: string }) { const [failed, setFailed] = useState(false); useEffect(() => setFailed(false), [model.coverPath, model.coverRevision]); return <div className={`cover ${className} kind-${model.type?.toLowerCase()}`}>{cover(model) && !failed ? <img src={cover(model)} alt={model.name} onError={() => setFailed(true)} loading="lazy"/> : <div className="cover-art"><div className="orb orb-one"/><div className="orb orb-two"/><span className="art-mark">{model.type === 'Checkpoint' ? 'C' : model.type === 'LORA' ? 'L' : 'M'}<span>✦</span></span><span className="art-caption">{typeLabel(model.type)}<small>LOCAL COLLECTION</small></span></div>}</div>; }
function Empty({ icon: Icon = Layers3, title, text, children }: any) { return <div className="empty"><div className="empty-icon"><Icon size={29}/></div><h3>{title}</h3><p>{text}</p>{children}</div>; }
function Modal({ title, subtitle, children, close, wide = false }: any) { useEffect(() => { const fn = (e: KeyboardEvent) => { if (e.key === 'Escape') close(); }; window.addEventListener('keydown', fn); return () => window.removeEventListener('keydown', fn); }, [close]); return <div className="overlay" onMouseDown={e => { if (e.target === e.currentTarget) close(); }}><section className={`modal ${wide ? 'wide' : ''}`} role="dialog" aria-modal="true" aria-label={title}><header className="modal-header"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><IconButton icon={X} label="关闭" onClick={close}/></header>{children}</section></div>; }

function App() {
  const [recipeTransfer,setRecipeTransfer]=useState<any>(null);
  const [data, setData] = useState<Snapshot | null>(null); const [fatal, setFatal] = useState('');
  const [page, setPage] = useState('library'); const [base, setBase] = useState('全部模型'); const [query, setQuery] = useState(''); const [type, setType] = useState('all'); const [sort, setSort] = useState('name'); const [favorites, setFavorites] = useState(false); const [limit, setLimit] = useState(60);
  const [category, setCategory] = useState('all');
  const [selected, setSelected] = useState<string | null>(null); const [importing, setImporting] = useState(false); const [editor, setEditor] = useState<Any | null>(null); const [collapsed, setCollapsed] = useState(false); const [toast, setToast] = useState<Any | null>(null); const [busy, setBusy] = useState<string[]>([]);
  const searchRef = useRef<HTMLInputElement>(null); const toastTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const notify = (text: string, error = false) => { clearTimeout(toastTimer.current); setToast({ text, error }); toastTimer.current = setTimeout(() => setToast(null), error ? 6500 : 3500); };
  const refreshSequence = useRef(0);
  const refresh = async () => { const sequence = ++refreshSequence.current; try { const next = await api('snapshot'); if (sequence === refreshSequence.current) setData(next); } catch (error) { if (sequence === refreshSequence.current) setFatal(errorText(error)); } };
  useEffect(() => { void refresh(); return window.studio.onChange(() => void refresh()); }, []);
  useEffect(() => { if (data?.settings?.uiTheme) applyTheme(data.settings.uiTheme); }, [data?.settings?.uiTheme]);
  useEffect(() => { setLimit(60); }, [base, type, query, favorites, category]);
  useEffect(() => { const fn = (e: KeyboardEvent) => { if ((e.ctrlKey || e.metaKey) && e.key === 'k') { e.preventDefault(); setPage('library'); searchRef.current?.focus(); } }; window.addEventListener('keydown', fn); return () => window.removeEventListener('keydown', fn); }, []);
  const run = async (key: string, action: () => Promise<any>, success?: string) => { if (busy.includes(key)) return; setBusy(b => [...b, key]); try { const result = await action(); if (success && result !== false) notify(success); await refresh(); return result; } catch (error) { notify(errorText(error), true); } finally { setBusy(b => b.filter(k => k !== key)); } };
  if (!data) return <div className="startup"><span className="brand-symbol"><Layers3 size={29}/></span><h1>模序</h1><p>{fatal || '正在打开你的本地创作空间…'}</p>{fatal ? <Button onClick={refresh}>重新连接</Button> : <Loader2 className="spin" size={21}/>}</div>;
  const frequency = recipeFrequencies(data.recipes);
  const models = data.models; const selectedModel = models.find(m => m.id === selected);
  const groups = baseGroups(models);
  const bases = [...new Set(models.flatMap(m => modelBases(m)))].sort((a, b) => a === '未知基模' ? 1 : b === '未知基模' ? -1 : a.localeCompare(b));
  const filtered = models.filter(m => matchesCategory(m, category) && (base === '全部模型' || matchesBaseFilter(m, base)) && (type === 'all' || (type === 'LORA' ? ['LORA', 'LoCon', 'DoRA'].includes(m.type) : m.type === type)) && (!favorites || m.favorite) && `${m.name} ${m.filename} ${baseLabel(m)} ${m.loraCategories?.join(' ')} ${m.tags?.join(' ')} ${m.triggerWords?.join(' ')}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sort === 'frequency' ? ((frequency[b.id] || 0) - (frequency[a.id] || 0) || a.name.localeCompare(b.name)) : sort === 'recent' ? (b.modified || 0) - (a.modified || 0) : sort === 'size' ? b.size - a.size : a.name.localeCompare(b.name));
  const activeDownloads = data.downloads.filter(d => ['queued', 'resolving', 'downloading', 'verifying', 'archiving'].includes(d.status));
  const totalSize = models.reduce((a, m) => a + (m.missing ? 0 : m.size), 0);
  const nav = [{ id: 'library', label: '模型库', sub: 'Library', icon: LayoutGrid }, { id: 'recipes', label: '配方记忆', sub: 'Recipes', icon: BookOpen }, { id: 'automation', label: '自动化编排', sub: 'Automation', icon: Workflow }, { id: 'outputs', label: '自动化输出', sub: 'Flow Outputs', icon: FolderOpen }, { id: 'downloads', label: '下载中心', sub: 'Downloads', icon: Download }, { id: 'results', label: '生成记录', sub: 'Results', icon: Image }];
  const newRecipe = (lora?: Model) => setEditor({ name: lora ? `${lora.name} · 配方` : '', checkpointId: models.find(m => m.type === 'Checkpoint' && !m.missing)?.id || '', loras: lora ? [loraDefault(lora)] : [], prompt: lora?.triggerWords?.join(', ') || '', negative: '', workflowBindings: { mode: 'full', memoryProfile: 'balanced' }, parameters: { width: 1024, height: 1024, steps: 25, cfg: 7, seed: '0', seedPolicy: 'random', sampler: 'euler', scheduler: 'normal' } });
  const shareRecipe=async(id:string)=>{const preview=await run('recipe-share-preview',()=>api('recipe-share:preview',{id}));if(preview)setRecipeTransfer({mode:'share',preview});};
  const loadRecipe=async()=>{const preview=await run('recipe-share-open',()=>api('recipe-share:open'));if(preview)setRecipeTransfer({mode:'load',preview});};
  return <div className={`app-shell ${collapsed ? 'sidebar-collapsed' : ''}`}>
    <aside className="sidebar"><div className="brand"><span className="brand-symbol"><Layers3 size={23}/></span><div><strong>模序<span>STUDIO</span></strong><small>你的本地模型创作空间</small></div></div><SidebarSections selectedBase={base} baseCount={groups.length} workspace={<nav>{nav.map(n => <button key={n.id} className={`nav-item ${page === n.id ? 'active' : ''}`} onClick={() => setPage(n.id)} title={n.label} aria-label={n.label}><n.icon size={18}/><span>{n.label}<small>{n.sub}</small></span>{n.id === 'downloads' && activeDownloads.length > 0 && <b>{activeDownloads.length}</b>}</button>)}</nav>} bases={<div className="base-nav"><button className={`base-item ${base === '全部模型' && page === 'library' ? 'selected' : ''}`} onClick={() => { setBase('全部模型'); setPage('library'); }}><span className="base-dot all"/>全部模型<small>{models.length}</small></button>{groups.map((group, i) => <div key={group.name} className="base-family"><button className={`base-item ${base === group.name && page === 'library' ? 'selected' : ''}`} onClick={() => { setBase(group.name); setPage('library'); }} title={group.name} aria-expanded={group.versions.length ? base === group.name || group.versions.includes(base) : undefined}><span className={`base-dot color-${i % 5}`}/><span>{group.name}</span>{group.versions.length > 0 && <ChevronRight className="base-family-chevron" size={12} style={{ transform: base === group.name || group.versions.includes(base) ? 'rotate(90deg)' : undefined }}/>}<small>{models.filter(m => matchesBaseFilter(m, group.name)).length}</small></button>{group.versions.length > 0 && (base === group.name || group.versions.includes(base)) && <div className="base-versions">{group.versions.map(name => <button key={name} className={`base-item ${base === name && page === 'library' ? 'selected' : ''}`} onClick={() => { setBase(name); setPage('library'); }} title={name}><span>{baseChoiceLabel(name, group.name)}</span><small>{models.filter(m => matchesBaseFilter(m, name)).length}</small></button>)}</div>}</div>)}</div>}/>
      <div className="sidebar-bottom"><div className="local-status"><span className="status-dot"/><div>本地资料库<small>{bytes(totalSize)} · {models.length} 个模型</small></div><ShieldCheck size={17}/></div><button className={`nav-item settings-nav ${page === 'settings' ? 'active' : ''}`} onClick={() => setPage('settings')} title="设置" aria-label="偏好设置"><Settings2 size={18}/><span>偏好设置</span></button><div className="sidebar-foot"><span>COMFY MODEL STUDIO</span><IconButton icon={collapsed ? PanelLeftOpen : PanelLeftClose} label={collapsed ? '展开侧栏' : '收起侧栏'} onClick={() => setCollapsed(!collapsed)}/></div></div>
    </aside>
    <main className="workspace"><header className="topbar"><div className="breadcrumb"><span>工作空间</span><ChevronRight size={13}/><strong>{[...nav, { id: 'settings', label: '偏好设置' }].find(n => n.id === page)?.label}</strong></div><div className="topbar-actions"><button className="shortcut-hint" onClick={() => { setPage('library'); searchRef.current?.focus(); }}>搜索 <kbd>Ctrl K</kbd></button></div></header>
    <div className={`page-content page-${page}`}>
    {page === 'library' && <>
      <div className="page-title"><div><div className="eyebrow">YOUR LOCAL COLLECTION</div><h1>{base === '全部模型' ? '模型库' : base}<span className="title-dot">.</span></h1><p>让每一个模型，都有属于它的位置。</p></div><div className="title-actions"><BaseRequirements items={data.baseRequirements} run={run} busy={busy}/><Button icon={FileDown} onClick={() => run('inventory', () => api('inventory:export'), '模型清单已导出')}>备份模型清单</Button><Button icon={RefreshCw} disabled={data.scanning} onClick={() => run('scan', () => api('scan'))}><span>{data.scanning ? '正在扫描…' : '扫描本地'}</span></Button><Button icon={Plus} className="primary" onClick={() => setImporting(true)}>获取模型</Button></div></div>
      <div className="collection-summary"><div><span className="summary-icon mint"><Layers3 size={20}/></span><div><strong>{models.length.toString().padStart(2, '0')}</strong><span>本地模型</span></div></div><div><span className="summary-icon peach"><Sparkles size={20}/></span><div><strong>{models.filter(m => ['LORA', 'LoCon', 'DoRA'].includes(m.type)).length.toString().padStart(2, '0')}</strong><span>LoRA 素材</span></div></div><div><span className="summary-icon lavender"><BookOpen size={20}/></span><div><strong>{data.recipes.length.toString().padStart(2, '0')}</strong><span>灵感配方</span></div></div><div className="summary-storage"><div><strong>{bytes(totalSize)}</strong><span>由你掌控，本地保存</span></div><span className="storage-art"><i/><i/><i/><i/><i/><i/><i/><i/></span></div></div>
      {models.length > 0 && models.every(m => !m.coverPath) && <div className="intro-strip"><span className="intro-icon"><Image size={19}/></span><div><strong>给模型补上第一眼的灵感</strong><span>打开模型详情，按哈希补全网站资料，或选择一张本地封面。</span></div></div>}
      <div className="library-toolbar"><div className="type-tabs">{[['all', '全部'], ['LORA', 'LoRA'], ['Checkpoint', 'Checkpoint'], ['VAE', 'VAE'], ['Upscaler', '放大模型']].map(([id, label]) => <button key={id} className={type === id ? 'selected' : ''} onClick={() => { setType(id); if (id !== 'LORA') setCategory('all'); }}>{label}</button>)}</div><div className="filter-actions"><RemovedModels count={data.removedModelCount} run={run} busy={busy} notify={notify}/><button className={`favorite-filter ${favorites ? 'selected' : ''}`} title="只看收藏" onClick={() => setFavorites(!favorites)}><Heart size={16} fill={favorites ? 'currentColor' : 'none'}/></button><Select aria-label="排序" value={sort} onChange={e => setSort(e.target.value)}><option value="name">名称排序</option><option value="recent">最近修改</option><option value="size">文件大小</option><option value="frequency">使用频率</option></Select></div></div>
      {type === 'LORA' && <div className="lora-secondary-row" role="group" aria-label="LoRA 二级分类筛选"><span>二级分类</span><div>{[['all', '全部分类'], ['none', '未分类'], ...data.loraCategories.map(label => [`tag:${label}`, label])].map(([value, label]) => <button key={value} type="button" aria-pressed={category === value} className={category === value ? 'selected' : ''} onClick={() => setCategory(value)}>{label}</button>)}{!data.loraCategories.length && <small>在模型详情中添加二级标签后，会显示在这里</small>}</div></div>}
      <div className="search-row"><div className="search-field"><Search size={17}/><input ref={searchRef} placeholder="搜索模型、文件名、标签或触发词…" value={query} onChange={e => setQuery(e.target.value)}/>{query && <IconButton icon={X} label="清空搜索" onClick={() => setQuery('')}/>}</div><span className="result-count">{filtered.length} 个模型</span></div>
      {filtered.length ? <><div className="model-grid">{filtered.slice(0, limit).map(model => <article className={`model-card ${model.missing ? 'missing' : ''}`} key={model.id}><button className="card-main" onClick={() => setSelected(model.id)}><Cover model={model}/><div className="card-image-top"><Badge>{typeLabel(model.type)}</Badge>{model.favorite && <Heart size={15} fill="currentColor"/>}</div><div className="card-image-bottom"><span>{baseLabel(model)}</span><span>{model.coverPath ? '本地封面' : '待添加封面'}</span></div><div className="card-info"><h3 title={model.name}>{model.name}</h3><p>{model.versionName || model.filename}</p>{sort === 'frequency' && ['LORA', 'LoCon', 'DoRA'].includes(model.type) && <Badge>使用频率 · {frequency[model.id] || 0} 个配方</Badge>}{model.loraCategories?.length > 0 && <div className="lora-category-chips">{model.loraCategories.map((label: string) => <span key={label}>{label}</span>)}</div>}<div className="card-meta"><span className={model.missing ? 'error-text' : ''}><span className={`tiny-dot ${model.missing ? 'red' : ''}`}/>{model.missing ? '文件缺失' : model.metadataStatus === 'complete' ? '资料已归档' : '本地已收录'}</span><span>{bytes(model.size)}</span></div></div></button><div className="card-hover-actions"><IconButton icon={Heart} label={model.favorite ? '取消收藏' : '收藏'} onClick={() => run(model.id, () => api('model:edit', { id: model.id, changes: { favorite: !model.favorite } }))}/><IconButton icon={ArrowUpRight} label="查看详情" onClick={() => setSelected(model.id)}/></div></article>)}</div>{filtered.length > limit && <div className="load-more"><Button onClick={() => setLimit(l => l + 60)}>加载更多 · 还剩 {filtered.length - limit} 个</Button></div>}</> : <Empty title={models.length ? '没有找到匹配的模型' : '你的模型库，从这里开始'} text={models.length ? '试试其他基模、类型或搜索词。' : '扫描已有 ComfyUI 模型，或从 Civitai 获取你的第一个模型。'}><Button icon={models.length ? X : Download} className="primary" onClick={() => models.length ? (setQuery(''), setType('all'), setBase('全部模型'), setFavorites(false), setCategory('all')) : setImporting(true)}>{models.length ? '清除筛选' : '获取模型'}</Button></Empty>}
    </>}
    {page === 'recipes' && <><div className="page-title"><div><div className="eyebrow">SAVE YOUR CREATIVE FORMULA</div><h1>配方记忆<span className="title-dot">.</span></h1><p>记住模型、权重与提示词，让灵感有迹可循。</p></div><div className="recipe-transfer-top-actions"><Button icon={FileUp} disabled={busy.includes('recipe-share-open')} onClick={()=>void loadRecipe()}>加载配方</Button><Button icon={Plus} className="primary" onClick={() => newRecipe()}>新建配方</Button></div></div><div className="section-note"><Info size={16}/><span>配方可以直接生成，也可以加入编排。每次运行都会冻结实际参数与工作流。</span></div>{data.recipes.length ? <div className="recipe-grid">{data.recipes.map(recipe => { const model = models.find(m => m.id === recipe.checkpointId); return <article className="recipe-card" key={recipe.id}><div className="recipe-cover"><RecipeCover recipe={recipe} fallback={model ? <Cover model={model}/> : <BookOpen size={30}/>}/><button type="button" className="recipe-cover-change" aria-label={`设置 ${recipe.name} 展示图`} onClick={() => setEditor(recipe)}><Image size={12}/>{recipe.coverId ? '更换展示图' : '设置展示图'}</button><span className="recipe-overlay">RECIPE <b>{String(data.recipes.indexOf(recipe) + 1).padStart(2, '0')}</b></span></div><div className="recipe-body"><div className="recipe-head"><h3>{recipe.name}</h3><Badge>v{recipe.revision}</Badge></div><p className="recipe-model"><Layers3 size={14}/>{model?.name || 'Checkpoint 已缺失'}</p><div className="recipe-loras">{recipe.loras.length ? recipe.loras.map((lora: Any, i: number) => <Badge key={i}>{isCharacterEntry(lora,models) ? '角色 · ' : ''}{models.find(m => m.id === lora.modelId)?.name || '未知 LoRA'} · {lora.strengthModel}</Badge>) : <span>纯 Checkpoint 配方</span>}</div><div className="recipe-footer"><span>{recipe.parameters.width} × {recipe.parameters.height} · {recipe.parameters.steps} steps</span><IconButton icon={ArrowUpRight} label="编辑配方" onClick={() => setEditor(recipe)}/></div><div className="recipe-actions"><Button icon={Workflow} onClick={async () => { const plan = structuredClone(data.plan); plan.items.push({ id: uid(), recipeId: recipe.id, enabled: true, groups: 1, imagesPerGroup: 10, overrides: { promptDefinitions:recipe.promptDefinitions,characterDefinitions:recipe.characterDefinitions,promptMode: recipe.promptMode, characterPrompt: recipe.characterPrompt, prompt: recipe.prompt, negative: recipe.negative, checkpointId: recipe.checkpointId, loras: recipe.loras, parameters: { ...recipe.parameters, seedPolicy: recipe.parameters.seedPolicy === 'fixed' ? 'increment' : recipe.parameters.seedPolicy } } }); await run('plan-add', () => api('plan:save', plan), '已加入自动化编排'); }}>加入编排</Button><Button icon={Sparkles} disabled={data.preparingRun || busy.includes('quick-recipe')} onClick={async () => { const result = await run('quick-recipe', () => api('run:recipe', { ...recipe, workflowBindings: { ...recipe.workflowBindings, mode: 'core' } }), '快速预览已启动'); if (result) setPage('outputs'); }}>快速预览</Button><Button icon={Play} disabled={data.preparingRun || busy.includes('run-recipe')} onClick={async () => { const result = await run('run-recipe', () => api('run:recipe', recipe), '已提交生成批次'); if (result) setPage('outputs'); }}>生成</Button><div className="recipe-edit-actions"><Button icon={Copy} aria-label={`复制配方 ${recipe.name}`} disabled={busy.includes(`recipe-copy-${recipe.id}`)} onClick={()=>run(`recipe-copy-${recipe.id}`,()=>api('recipe:duplicate',{id:recipe.id}),'配方已复制，可在副本中编辑')}>复制</Button><Button onClick={() => setEditor(recipe)}>编辑</Button></div><Button icon={FileDown} className="recipe-share-action" aria-label={`分享配方 ${recipe.name}`} disabled={busy.includes('recipe-share-preview')} onClick={()=>void shareRecipe(recipe.id)}>分享配方</Button></div></div></article>; })}</div> : <Empty icon={BookOpen} title="留住一次满意的组合" text="选择 Checkpoint、叠加 LoRA，写下提示词，保存为你的专属配方。"><Button icon={Plus} className="primary" onClick={() => newRecipe()}>创建第一个配方</Button></Empty>}</>}
    {page === 'automation' && <Automation data={data} run={run} busy={busy} notify={notify} openOutputs={() => setPage('outputs')}/>}
    {page === 'outputs' && <AutomationOutputs data={data} run={run} busy={busy} notify={notify} openRecords={() => setPage('results')}/>}
    {page === 'results' && <ImageAlbums data={data} run={run} busy={busy} notify={notify}/>}
    {page === 'downloads' && <><div className="page-title"><div><div className="eyebrow">FROM THE WEB TO YOUR WORKSPACE</div><h1>下载中心<span className="title-dot">.</span></h1><p>模型、封面与说明，一次归档到正确的位置。</p></div><div className="title-actions download-bulk-actions"><Button icon={Pause} disabled={busy.includes('downloads-bulk') || !activeDownloads.length} onClick={async () => { const result = await run('downloads-bulk', () => api('download:bulk', { action: 'pause' })); if (result) notify(`已暂停 ${result.paused} 个任务，新增任务也会等待开始`); }}>一键暂停</Button><Button icon={Play} disabled={busy.includes('downloads-bulk') || (!data.downloadQueuePaused && !data.downloads.some(job => ['paused', 'failed', 'partial', 'queued'].includes(job.status)))} onClick={async () => { const result = await run('downloads-bulk', () => api('download:bulk', { action: 'start' })); if (result) notify(`下载队列已开始 · ${result.queued} 个任务按顺序执行`); }}>一键开始</Button><Button icon={Plus} className="primary" onClick={() => setImporting(true)}>新建下载</Button></div></div><div className="download-summary"><span><i className="status-dot"/>{activeDownloads.length} 个进行中</span><span>{data.downloadQueuePaused ? '新增任务保持暂停 · 点击“一键开始”恢复' : '完成后自动移除记录 · 模型留在模型库'}</span><span>下载后自动校验 SHA256</span></div><p className="download-bulk-help">一键开始会继续暂停和等待任务，并重试失败或封面待补全的任务；按当前列表顺序逐个执行。</p>{data.downloads.length ? <div className="download-list">{data.downloads.map(job => <div className={`download-item state-${job.status}`} key={job.id}><div className="download-file-icon">{job.status === 'complete' ? <CheckCircle2 size={23}/> : job.status === 'failed' ? <CircleAlert size={23}/> : <Download size={23}/>}</div><div className="download-body"><div className="download-name"><strong>{job.name}</strong><Badge>{typeLabel(job.type)}</Badge><span>{job.status === 'downloading' && job.phase === 'merging' ? '合并下载分段' : statusLabel[job.status]}</span></div><p>{job.filename}</p><div className="progress-track"><i style={{ width: `${job.status === 'complete' ? 100 : Math.min(100, (job.received || 0) / Math.max(1, job.total) * 100)}%` }}/></div><div className="download-meta"><span>{bytes(job.received)} / {bytes(job.total)}{job.transferMode === 'parallel' && ` · ${job.connections || 4} 路分段`}{job.speed > 0 && ` · ${bytes(job.speed)}/s`}</span><span title={job.destination}>{job.destination}</span></div>{job.error && <p className="download-error">{job.error}</p>}</div><div className="download-actions">{['downloading', 'queued', 'resolving', 'verifying', 'archiving'].includes(job.status) && <IconButton icon={Pause} label="暂停" onClick={() => run(job.id, () => api('download:action', { id: job.id, action: 'pause' }))}/>} {['failed', 'paused', 'partial'].includes(job.status) && <IconButton icon={RefreshCw} label="重试 / 继续" onClick={() => run(job.id, () => api('download:action', { id: job.id, action: 'retry' }))}/>} {!['complete', 'canceled'].includes(job.status) && <IconButton icon={X} label="取消并移除任务" onClick={() => run(job.id, () => api('download:action', { id: job.id, action: 'cancel' }))}/>}</div></div>)}</div> : <Empty icon={Download} title={data.downloadQueuePaused ? '下载队列已暂停' : '当前没有待处理的下载'} text={data.downloadQueuePaused ? '新增任务会保持暂停，点击上方“一键开始”恢复自动下载。' : '下载成功后记录会自动移除，模型、封面与说明保存在模型库。可粘贴模型链接继续下载。'}><Button icon={Link2} className="primary" onClick={() => setImporting(true)}>粘贴模型链接</Button></Empty>}</>}
    {page === 'settings' && <Settings data={data} run={run} busy={busy} notify={notify}/>}
    </div><footer className="workspace-footer"><span><span className="tiny-dot"/> {data.scanning ? '正在扫描本地模型…' : '所有资料存储在你的电脑上'}</span><span>模序 {data.version} <span className="footer-separator">/</span> MADE FOR YOUR CREATIVE FLOW</span></footer></main>
    {activeDownloads.length > 0 && page !== 'downloads' && <button className="download-floating" onClick={() => setPage('downloads')}><span className="floating-icon"><Download size={18}/></span><div><strong>{activeDownloads[0].status === 'verifying' ? '正在校验模型' : '模型正在归档途中'}</strong><span>{activeDownloads.length} 个任务 · {bytes(activeDownloads[0].received)} / {bytes(activeDownloads[0].total)}</span></div><ChevronRight size={17}/></button>}
    {recipeTransfer?.mode==='share'&&<RecipeShareModal preview={recipeTransfer.preview} run={run} busy={busy} notify={notify} close={()=>setRecipeTransfer(null)}/>}
    {recipeTransfer?.mode==='load'&&<RecipeLoadModal preview={recipeTransfer.preview} models={models} run={run} busy={busy} notify={notify} close={()=>setRecipeTransfer(null)} onSaved={()=>setPage('recipes')}/>}
    {selectedModel && <ModelDetail bases={bases} categories={data.loraCategories} model={selectedModel} busyKeys={busy} busy={busy.includes(selectedModel.id)} close={() => setSelected(null)} run={run} notify={notify} onRecipe={() => { newRecipe(['LORA', 'LoCon', 'DoRA'].includes(selectedModel.type) ? selectedModel : undefined); if (selectedModel.type === 'Checkpoint') setEditor((r: any) => ({ ...r, checkpointId: selectedModel.id })); }}/>} 
    {importing && <ImportModal categories={data.loraCategories} close={() => setImporting(false)} run={run} busy={busy} done={() => { setImporting(false); setPage('downloads'); }} origin={data.settings.sourceOrigin}/>}
    {editor && <RecipeEditor recipe={editor} models={models} data={data} notify={notify} close={() => setEditor(null)} run={run} busy={busy.includes('recipe-save')}/>}
    {toast && <div className={`toast ${toast.error ? 'error' : ''}`} role="status">{toast.error ? <CircleAlert size={18}/> : <CheckCircle2 size={18}/>}<span>{toast.text}</span><IconButton icon={X} label="关闭提示" onClick={() => setToast(null)}/></div>}
  </div>;
}

function ModelDetail({ model, bases, categories, busyKeys, close, run, busy, notify, onRecipe }: any) {
  const [tab, setTab] = useState('details'); const [editing, setEditing] = useState(false); const [draft, setDraft] = useState<Any>({});
  useEffect(() => { const fn = (e: KeyboardEvent) => { if (e.key === 'Escape') close(); }; window.addEventListener('keydown', fn); return () => window.removeEventListener('keydown', fn); }, [close]);
  const copy = async (text: string) => { try { await navigator.clipboard.writeText(text); notify('已复制触发词'); } catch { notify('复制失败，请手动选择文本', true); } };
  const readme = DOMPurify.sanitize(tab === 'version' ? model.versionDescription || '' : model.description || '', { FORBID_TAGS: ['img', 'video', 'audio', 'iframe', 'form', 'input', 'style'], FORBID_ATTR: ['style', 'srcset'], ADD_ATTR: ['target'] });
  return <div className="drawer-overlay" onMouseDown={e => { if (e.target === e.currentTarget) close(); }}><aside className="detail-drawer" role="dialog" aria-modal="true" aria-label="模型详情"><header className="drawer-header"><span>模型档案 <span>MODEL PROFILE</span></span><IconButton icon={X} label="关闭详情" onClick={close}/></header><div className="detail-scroll"><Cover model={model} className="detail-cover"/><div className="detail-heading"><div className="detail-badges"><Badge tone="mint">{typeLabel(model.type)}</Badge><Badge>{baseLabel(model)}</Badge></div><h2>{model.name}</h2><p>{model.versionName || model.filename}</p><div className="detail-actions"><DeleteModel model={model} run={run} busy={busyKeys} notify={notify} onDeleted={close}/><Button className="primary" icon={BookOpen} onClick={onRecipe}>创建配方</Button><Button icon={FolderOpen} onClick={() => api('model:reveal', { id: model.id })}>本地文件</Button><IconButton icon={Heart} label="收藏" onClick={() => run(model.id, () => api('model:edit', { id: model.id, changes: { favorite: !model.favorite } }))}/></div></div>
<div className="detail-tools"><Button icon={RefreshCw} disabled={busy || model.missing} onClick={async () => { const result = await run(model.id, () => api('model:enrich', { id: model.id })); if (result) notify(result.coverError ? `资料已补全，封面待处理：${result.coverError}` : '网站资料和封面已补全', Boolean(result.coverError)); }}>{busy ? '正在计算哈希 / 获取资料…' : '按哈希补全网站资料'}</Button><Button icon={Image} onClick={() => run(model.id, () => api('model:cover', { id: model.id }), '封面已更新')}>选择本地封面</Button><Button icon={SlidersHorizontal} onClick={() => { setDraft({ name: model.name, baseModels: normalizeBaseModels(model.baseModels ?? model.baseModel).filter(b => b !== '未知基模'), triggerWords: (model.triggerWords || []).join(', '), tags: (model.tags || []).join(', '), notes: model.notes || '', loraCategories: model.loraCategories || [] }); setEditing(!editing); }}>手动整理资料</Button>{model.sourceUrl && <Button icon={ExternalLink} onClick={() => api('external:open', { url: model.sourceUrl })}>打开来源页面</Button>}</div>
    <div className="detail-tabs">{[['details', '模型详情'], ['readme', '模型说明'], ['version', '版本说明']].map(([id, name]) => <button key={id} className={tab === id ? 'selected' : ''} onClick={() => setTab(id)}>{name}</button>)}</div>
    {tab === 'details' ? <div className="detail-section"><div className="section-heading"><h3>触发词</h3><button onClick={() => copy(model.triggerWords?.join(', ') || '')} disabled={!model.triggerWords?.length}><Copy size={13}/>全部复制</button></div><div className="trigger-list">{model.triggerWords?.length ? model.triggerWords.map((word: string) => <button key={word} onClick={() => copy(word)}>{word}<Copy size={12}/></button>) : <span className="muted">暂未记录触发词</span>}</div><div className="detail-facts">{[['类型', typeLabel(model.type)], ['基础模型', baseLabel(model)], ['作者推荐权重', model.recommendedStrength ? `${model.recommendedStrength.min}–${model.recommendedStrength.max} · 默认 ${model.recommendedStrength.value}` : '未提供明确建议'], ['基模信息来源', ({ api: '网站 API', manual: '手动整理', inferred: '文件信息推断，建议核验' } as Any)[model.baseModelSource] || '本地资料'], ['作者', model.creator || '尚未补全'], ['文件大小', bytes(model.size)], ['发布时间', model.publishedAt ? new Date(model.publishedAt).toLocaleDateString('zh-CN') : '尚未补全'], ['版本 / 文件 ID', model.versionId ? `${model.versionId} / ${model.fileId}` : '尚未关联网站版本'], ['格式 / 精度', [model.fileMetadata?.format, model.fileMetadata?.fp].filter(Boolean).join(' / ') || model.filename.split('.').pop()], ['下载量', model.stats?.downloadCount?.toLocaleString() || '—']].map(([label, value]) => <div key={label}><span>{label}</span><strong>{value}</strong></div>)}</div><PageDetails details={model.pageDetails} model={model}/>{model.air && <div className="info-block"><label>AIR</label><code>{model.air}</code></div>}{model.sha256 && <div className="info-block"><label>SHA256</label><code>{model.sha256}</code></div>}<div className="info-block"><label>本地路径</label><code>{model.path}</code></div>{model.tags?.length > 0 && <div className="tag-list">{model.tags.map((tag: string) => <Badge key={tag}>{tag}</Badge>)}</div>}
    <div className="lora-category-chips">{['LORA', 'LoCon', 'DoRA'].includes(model.type) && (model.loraCategories?.length ? model.loraCategories.map((label: string) => <span key={label}>{label}</span>) : <span>二级分类：未分类</span>)}</div>
    {editing && <div className="inline-edit"><BaseModelEditor detected={model.baseTargets || []} value={draft.baseModels || []} suggestions={bases} onChange={baseModels => setDraft((current: Any) => ({ ...current, baseModels }))}/>{['LORA', 'LoCon', 'DoRA'].includes(model.type) && <CategoryPicker value={draft.loraCategories} categories={categories} onChange={value => setDraft({ ...draft, loraCategories: value })}/>}{[['name', '模型名称'], ['triggerWords', '触发词 · 用逗号分隔'], ['tags', '标签 · 用逗号分隔'], ['notes', '我的备注']].map(([key, label]) => <label className="field" key={key}><span>{label}</span><input value={draft[key]} onChange={e => setDraft({ ...draft, [key]: e.target.value })}/></label>)}<Button className="primary" icon={Save} disabled={busy} onClick={async () => { const result = await run(model.id, () => api('model:edit', { id: model.id, changes: { ...draft, triggerWords: draft.triggerWords.split(/[,，]/).map((s: string) => s.trim()).filter(Boolean), tags: draft.tags.split(/[,，]/).map((s: string) => s.trim()).filter(Boolean) } }), '模型资料已保存'); if (result) setEditing(false); }}>保存资料</Button></div>}{model.notes && <div className="info-block"><label>我的备注</label><p>{model.notes}</p></div>}</div> : <div className="readme" onClick={e => { const a = (e.target as HTMLElement).closest('a'); if (a) { e.preventDefault(); void api('external:open', { url: a.href }); } }}>{readme ? <div dangerouslySetInnerHTML={{ __html: readme }}/> : <Empty icon={FileJson} title="暂未保存说明" text="按哈希补全网站资料后，可在这里离线阅读作者说明。"/>}</div>}
    </div></aside></div>;
}

function ImportModal({ categories, close, run, busy, done, origin }: any) {
  const [loraCategories, setLoraCategories] = useState<string[]>([]);
  const [url, setUrl] = useState(''); const [preview, setPreview] = useState<Any | null>(null); const [fileId, setFileId] = useState(''); const previewRequest = useRef(0); const renderedRequest = previewRequest.current;
  return <Modal title="获取模型" subtitle="粘贴链接即可下载模型与资料。" close={close}><div className="modal-body"><label className="field"><span>模型页面链接</span><div className="input-with-icon"><Link2 size={16}/><input autoFocus placeholder={`${origin}/models/…?modelVersionId=…`} value={url} onChange={e => { previewRequest.current++; setUrl(e.target.value); setPreview(null); }}/></div></label><p className="field-help">建议复制带 modelVersionId 的链接，以准确选择版本。未指定版本时使用最新版本。</p>{!preview ? <Button className="primary full" icon={busy.includes('preview') ? Loader2 : Search} disabled={!url.trim() || busy.includes('preview')} onClick={async () => { const request = ++previewRequest.current; const result = await run('preview', () => api('acquisition:preview', { url })); if (result && request === previewRequest.current) { setPreview(result); setFileId(String(result.files.find((f: Any) => f.primary)?.id || result.files[0].id)); } }}>{busy.includes('preview') ? '正在读取模型资料…' : '读取模型信息'}</Button> : <div className="import-preview"><div className="import-preview-icon"><Layers3 size={27}/></div><div><h3>{preview.name}</h3><p>{preview.versionName}</p><div className="tag-list"><Badge tone="mint">{typeLabel(preview.type)}</Badge><Badge>{preview.baseModel}</Badge><Badge>{preview.imageCount} 张可选静态预览</Badge></div></div><AcquisitionVersions preview={preview} run={run} busy={busy} categories={loraCategories} done={done} onChange={(result: Any) => { if (renderedRequest !== previewRequest.current) return; setPreview(result); setFileId(String(result.files.find((f: Any) => f.primary)?.id || result.files[0].id)); }}/><label className="field full"><span>下载文件</span><Select aria-label="下载文件" disabled={busy.includes('version-preview') || busy.includes('bundle-download')} value={fileId} onChange={e => setFileId(e.target.value)}>{preview.files.map((f: Any) => <option key={f.id} value={f.id}>{f.name} · {bytes(f.sizeKB * 1024)} {f.primary ? '· 推荐主文件' : ''}</option>)}</Select></label>{['LORA', 'LoCon', 'DoRA'].includes(preview.type) && <div className="full"><CategoryPicker value={loraCategories} categories={categories} onChange={setLoraCategories}/></div>}<p className="field-help full">将保存模型、第一张静态封面、模型与版本说明及 API 详情。目标路径由类型设置决定。</p><Button className="primary full" icon={Download} disabled={busy.includes('create-download') || busy.includes('version-preview') || busy.includes('bundle-download')} onClick={async () => { const result = await run('create-download', () => api('download:create', { origin: preview.origin, versionId: preview.versionId, fileId: Number(fileId), loraCategories }), '已加入下载队列'); if (result) done(); }}>{busy.includes('create-download') ? '正在建立任务…' : '下载并入库'}</Button></div>}<div className="modal-tip"><ShieldCheck size={17}/><span>API Key 在桌面设置中加密保存。仅用于对应模型来源的请求。</span></div></div></Modal>;
}

function RecipeEditor({ recipe, models, data, notify, close, run, busy }: any) {
  const [draft, setDraft] = useState<Any>(() => splitRecipePrompt({ ...structuredClone(recipe), loras: (recipe.loras || []).map((entry: Any) => ({ ...entry, role: entry.role || (isCharacterEntry(entry,models) ? 'character' : 'general') })) },models)); const [coverBusy,setCoverBusy] = useState(false);
  const coverModel = models.find((model: Model) => model.id === draft.checkpointId);
  return <Modal wide title={recipe.id ? '编辑配方' : '新建配方'} subtitle="把模型组合与提示词，保存成下一次灵感的起点。" close={close}><div className="recipe-editor"><div className="editor-left"><label className="field"><span>配方名称</span><input autoFocus placeholder="例如：柔光人像 · 晨间" value={draft.name} onChange={e => setDraft({ ...draft, name: e.target.value })}/></label><RecipeCoverEditor draft={draft} data={data} fallback={coverModel ? <Cover model={coverModel}/> : <BookOpen size={25}/>} onChange={(cover: Any) => setDraft((current: Any) => ({ ...current, ...cover }))} onBusy={setCoverBusy} notify={notify}/><div className="section-heading"><h3>01 <span>基础模型</span></h3><Badge>Checkpoint</Badge></div><label className="field"><CheckpointPicker models={models} value={draft.checkpointId} onChange={checkpointId => setDraft((current: Any) => ({ ...current, checkpointId }))}/></label><div className="section-heading"><h3>02 <span>LoRA 组合</span></h3><span className="muted">按列表顺序叠加</span></div><RecipeLoras models={models} loras={draft.loras} onChange={(loras: Any[], prompt?: string) => setDraft((current: Any) => ({ ...current, loras, ...(prompt === undefined ? {} : { prompt }) }))} checkpointBase={modelBases(models.find((model: Model) => model.id === draft.checkpointId)).join(', ')} prompt={draft.prompt} onPromptChange={(prompt: string) => setDraft((current: Any) => ({ ...current, prompt }))} run={run}/><div className="section-heading"><h3>03 <span>生成参数</span></h3></div><Parameters choices={data.generationChoices} value={draft.parameters} onChange={(parameters: Any) => setDraft({ ...draft, parameters })}/><WorkflowPicker value={draft} files={data.workflowFiles} defaultPath={data.settings.defaultWorkflowPath} notify={notify} onChange={(patch: Any) => setDraft({ ...draft, ...patch })}/></div><div className="editor-right"><PromptBlocks recipe={draft} models={models} onChange={(patch:Any)=>setDraft((current:Any)=>({...current,...patch}))}/><div className="field"><span>负向提示词</span><PromptEditor label="配方负向提示词" rows={5} placeholder="可选，记录需要避免的内容" value={draft.negative} onChange={negative => setDraft((current: Any) => ({ ...current, negative }))}/></div><label className="field"><span>配方备注</span><textarea rows={3} placeholder="记录风格、适用场景与灵感" value={draft.notes || ''} onChange={e => setDraft({ ...draft, notes: e.target.value })}/></label><div className="modal-tip"><Info size={16}/><span>运行使用这里选择的工作流。配方文本会替换正负编码节点的文本输入；参数、模型和 LoRA 顺序会冻结到运行快照。</span></div></div></div><footer className="modal-footer"><div>{recipe.id && <Button className="danger-text" icon={Trash2} onClick={async () => { if (confirm('删除该配方？已有修订仍会保留，编排中的相关任务会移除。')) { await run('recipe-delete', () => api('recipe:delete', { id: recipe.id }), '配方已删除'); close(); } }}>删除配方</Button>}</div><div><Button onClick={close}>取消</Button><Button icon={CheckCircle2} disabled={busy || coverBusy || !composeRecipePrompt(draft).trim() || !draft.checkpointId} onClick={async () => { const result = await run('workflow-check', () => api('workflow:check', draft)); if (result) notify(result.ok ? `检查通过 · ${result.nodeCount} 个有效节点` : result.issues.map((i: Any) => i.message).join('；'), !result.ok); }}>检查工作流</Button><Button icon={Save} className="primary" disabled={busy || coverBusy || !composeRecipePrompt(draft).trim() || !draft.name.trim() || !draft.checkpointId} onClick={async () => { const saved = await run('recipe-save', () => api('recipe:save', draft), '配方已保存'); if (saved) close(); }}>保存配方</Button></div></footer></Modal>;
}

applyTheme(readTheme());
const planAutosaver = new PlanAutosaver((plan) => window.studio.call('plan:autosave', plan), window.localStorage);
function Automation({ data, run, busy, notify, openOutputs }: any) {
  const [inspectorOpen, setInspectorOpen] = useState(false);
  const migratePlan=(value:Any)=>({...value,...(!value.savedPlanId&&value.nameSpecified!==true&&value.name==='我的自动化编排'?{name:'',nameSpecified:false}:{}),items:value.items.map((item:Any)=>{const recipe=data.recipes.find((row:Any)=>row.id===item.recipeId);const split=splitRecipePrompt(taskRecipe(recipe,item.overrides),data.models);return {...item,overrides:{...item.overrides,promptDefinitions:split.promptDefinitions,characterDefinitions:split.characterDefinitions,promptMode:split.promptMode,prompt:split.prompt,loras:split.loras}};}),characterSlot:value.characterSlot?splitRecipePrompt(value.characterSlot,data.models):undefined});
  const [plan, setPlan] = useState<Any>(() => migratePlan(planAutosaver.initial(data.plan))); const [category, setCategory] = useState('all');
  const [selected, setSelected] = useState<string | null>(plan.items[0]?.id || null); const [, refreshSave] = useState(0);
  useEffect(() => { const unsubscribe = planAutosaver.subscribe(() => refreshSave(n => n + 1)); planAutosaver.edit(planRef.current); void planAutosaver.flush(); return unsubscribe; }, []); const drag = useRef(-1); const [bulkQuantity, setBulkQuantity] = useState(10);
  const planRef = useRef(plan); planRef.current = plan;
  const edit = (next: Any) => { planRef.current = next; setPlan(next); planAutosaver.edit(next); };
  const update = (id: string, patch: Any) => {
    const current=planRef.current,item=current.items.find((row: Any)=>row.id===id),recipe=data.recipes.find((row: Any)=>row.id===item?.recipeId);
    if (patch.overrides && current.characterSlot?.enabled) patch={...patch,overrides:mergeCharacterNodeEdit({...recipe,...item?.overrides},patch.overrides,current.characterSlot,data.models)};
    edit(patchPlanTask(current,id,patch));
  };
  const saveTask = async () => { planAutosaver.edit(planRef.current); await planAutosaver.flush(); if (planAutosaver.status === 'error') { notify(`保存失败：${planAutosaver.error}`, true); return; } notify('任务设置已保存到当前编排，原配方不变'); };

  const item = plan.items.find((i: Any) => i.id === selected); const recipe = data.recipes.find((r: Any) => r.id === item?.recipeId);
  const add = (recipeId: string) => { const r = data.recipes.find((r: Any) => r.id === recipeId); if (!r) return; const split=splitRecipePrompt(r,data.models); const next = { id: uid(), recipeId, enabled: true, candidateCount: 10, groups: 1, imagesPerGroup: 10, overrides: { promptDefinitions:split.promptDefinitions,characterDefinitions:split.characterDefinitions,promptMode: split.promptMode, characterPrompt: split.characterPrompt, prompt: split.prompt, negative: r.negative, checkpointId: r.checkpointId, loras: structuredClone(split.loras), parameters: { ...structuredClone(r.parameters), seedPolicy: r.parameters.seedPolicy === 'fixed' ? 'increment' : r.parameters.seedPolicy } } }; edit({ ...plan, items: [...plan.items, next] }); setSelected(next.id); };
  const total = plan.items.filter((i: Any) => i.enabled).reduce((n: number, i: Any) => n + Number(i.groups) * Number(i.imagesPerGroup), 0);
  const rawOverrides = item ? { ...recipe, ...(item.overrides || {}) } : null;
  const overrides = rawOverrides ? characterNodeBase(rawOverrides,plan.characterSlot,data.models) : null;
  const effectiveCharacterRecipe = rawOverrides ? applyCharacterSlot(rawOverrides,plan.characterSlot,data.models) : null;
  return <><div className="page-title automation-page-title"><div><div className="eyebrow">AUTOMATION STUDIO</div><h1>自动化编排<span className="title-dot">.</span></h1><p>组织配方顺序，统一角色与生成参数。</p></div><Button icon={Image} onClick={openOutputs}>查看自动化输出</Button></div>
  {planAutosaver.status==='error'&&<div className="automation-save-error" role="alert"><CircleAlert size={16}/><span>{planAutosaver.error||'编排保存失败'}</span><Button onClick={()=>void planAutosaver.flush()}>重试保存</Button></div>}
  <section className="automation-plan-panel" aria-label="编排方案"><header className="automation-section-title"><h2>编排方案</h2><div><Badge>{plan.items.filter((it:Any)=>it.enabled).length} 个启用任务</Badge><Badge>{total} 张计划图片</Badge></div></header><label className="automation-name"><span>当前编排名</span><input aria-label="编排名" placeholder="留空：时间戳＋全部节点名称" value={plan.name} onChange={event=>edit({...plan,name:event.target.value,nameSpecified:!!event.target.value.trim()})}/></label><PlanLibrary rows={data.planTemplates || []} plan={plan} onLoad={(loaded: Any) => { edit(migratePlan(loaded)); setSelected(loaded.items[0]?.id || null); setInspectorOpen(false); }} flush={async () => { await planAutosaver.flush(); if (planAutosaver.status === 'error') throw new Error(planAutosaver.error); }} run={run} notify={notify}/></section>
  <CharacterSlot plan={plan} models={data.models} recipes={data.recipes} onChange={edit} run={run} notify={notify}/>
  <section className="automation-options-panel" aria-label="运行设置"><div className="automation-generation"><header className="automation-section-title"><h2>生成选项</h2></header><div className="automation-option-grid"><label className="automation-option"><input type="checkbox" checked={plan.quickPreview===true} onChange={event=>edit({...plan,quickPreview:event.target.checked})}/><span><strong>快速预览</strong><small>仅基础文生图，跳过细化与放大</small></span></label><label className="automation-option"><input type="checkbox" checked={plan.randomizeSeeds!==false} onChange={event=>edit({...plan,randomizeSeeds:event.target.checked})}/><span><strong>每张使用不同随机种子</strong><small>关闭后按各任务的种子策略复现</small></span></label></div><div className="candidate-bulk"><label htmlFor="automation-bulk-count">每个配方备选</label><input id="automation-bulk-count" aria-label="统一备选数量" type="number" min="1" max="1000" value={bulkQuantity} onChange={event=>setBulkQuantity(Number(event.target.value))}/><span>张</span><Button disabled={!plan.items.length||!Number.isInteger(bulkQuantity)||bulkQuantity<1||bulkQuantity>1000} onClick={()=>edit({...plan,items:plan.items.map((it:Any)=>({...it,candidateCount:bulkQuantity,groups:1,imagesPerGroup:bulkQuantity}))})}>应用到全部配方</Button></div></div><div className="automation-directory"><header className="automation-section-title"><h2>输出位置</h2></header><DirectoryField compact label="输出目录（留空使用默认）" value={plan.outputDirectory||''} placeholder={data.automationOutputs?.root} onChange={(value:string)=>edit({...plan,outputDirectory:value})}/></div></section>
  <div className="automation-canvas-heading"><div><h2>任务编排</h2><p>拖动调整顺序，点击卡片配置任务。</p></div><Select aria-label="添加配方到编排" value="" onChange={event=>add(event.target.value)}><option value="">＋ 添加已有配方</option>{data.recipes.map((row:Any)=><option key={row.id} value={row.id}>{row.name}</option>)}</Select></div>
  <div className="automation-layout"><div className="workflow-canvas">{plan.items.length ? <div className="flow-chain"><div className="flow-start"><Play size={12}/> 开始</div>{plan.items.map((it: Any, i: number) => { const r = data.recipes.find((r: Any) => r.id === it.recipeId); const m = data.models.find((m: Model) => m.id === (it.overrides?.checkpointId || r?.checkpointId)); const effectiveTask = applyCharacterSlot({ ...r, ...it.overrides },plan.characterSlot,data.models); const taskLoraGroups=recipeLoraGroups(effectiveTask,data.models,plan.characterSlot?.enabled?plan.characterSlot:undefined); return <React.Fragment key={it.id}><div className="flow-connector"><ChevronDown size={16}/></div><article className={`flow-card ${selected === it.id ? 'selected' : ''} ${!it.enabled ? 'disabled' : ''}`} tabIndex={0} onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setSelected(it.id); setInspectorOpen(true); } }} draggable onDragStart={e => { drag.current = i; e.dataTransfer.setData('text/plain', String(i)); e.dataTransfer.effectAllowed = 'move'; }} onDragEnd={() => { drag.current = -1; }} onClick={() => { setSelected(it.id); setInspectorOpen(true); }} onDragOver={e => e.preventDefault()} onDrop={e => { e.preventDefault(); edit({ ...plan, items: move(plan.items, drag.current, i) }); drag.current = -1; }}><div className="flow-card-top"><span className="drag-handle" tabIndex={0} onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setSelected(it.id); setInspectorOpen(true); } }} draggable onDragStart={e => { drag.current = i; e.dataTransfer.setData('text/plain', String(i)); e.dataTransfer.effectAllowed = 'move'; }}><GripVertical size={17}/></span><span className="flow-index">{String(i + 1).padStart(2, '0')}</span><strong>{r?.name || '配方已删除'}</strong><button className={`toggle ${it.enabled ? 'on' : ''}`} role="switch" aria-checked={it.enabled} aria-label="启用任务" onClick={e => { e.stopPropagation(); update(it.id, { enabled: !it.enabled }); }}><i/></button></div><div className="flow-card-body">{m && <Cover model={m}/>}<div><p>{m?.name || '未选择 Checkpoint'}</p><span>{taskLoraGroups.general.length} 素材 LoRA <b>·</b> {it.candidateCount ?? Number(it.groups) * Number(it.imagesPerGroup)} 张备选</span><p className="flow-prompt">{promptPreview(effectiveTask)}</p></div></div><NodeCharacters recipe={effectiveTask} models={data.models} slot={plan.characterSlot} compact/><div className="flow-card-footer"><button className="button" onClick={e => { e.stopPropagation(); setSelected(it.id); setInspectorOpen(true); }}>配置任务</button><div onClick={e => e.stopPropagation()}><IconButton icon={ArrowUp} label="上移任务" disabled={i === 0} onClick={() => edit({ ...plan, items: move(plan.items, i, i - 1) })}/><IconButton icon={ArrowDown} label="下移任务" disabled={i === plan.items.length - 1} onClick={() => edit({ ...plan, items: move(plan.items, i, i + 1) })}/><IconButton icon={Copy} label="复制任务" onClick={() => { const copy = { ...structuredClone(it), id: uid() }; const items = [...plan.items]; items.splice(i + 1, 0, copy); edit({ ...plan, items }); }}/><IconButton icon={Trash2} label="移除任务" onClick={() => edit({ ...plan, items: plan.items.filter((x: Any) => x.id !== it.id) })}/></div></div></article></React.Fragment>; })}<div className="flow-connector"><ChevronDown size={16}/></div><div className="flow-end"><Check size={13}/> 完成</div></div> : <Empty icon={Workflow} title="下一次创作，由你编排" text="先保存一个配方，再从右上方添加到任务链。"/>}</div>{inspectorOpen && <div className="inspector-backdrop" onClick={() => setInspectorOpen(false)}/>}<aside className={`flow-inspector ${inspectorOpen ? 'inspector-open' : 'inspector-closed'}`}><header><button className="icon-button" aria-label="关闭任务配置" onClick={() => setInspectorOpen(false)}><X size={18}/></button><SlidersHorizontal size={17}/><h3>任务设置</h3><span>INSPECTOR</span></header>{item && recipe && overrides ? <div className="inspector-scroll"><div className="inspector-title"><span>选中配方</span><strong>{recipe.name}</strong></div><CandidateQuantity item={item} onChange={(patch: Any) => update(item.id, patch)}/>{overrides.parameters?.seedPolicy === 'fixed' && <p className="field-help">当前使用固定种子。想获得不同备选，可在下方将种子策略改为递增或随机。</p>}<label className="field"><span>本次 Checkpoint</span><CheckpointPicker models={data.models} value={overrides.checkpointId} onChange={checkpointId => update(item.id, { overrides: { checkpointId } })}/></label><div className="section-heading"><h3>本次 LoRA 组合</h3></div><RecipeLoras inherited={plan.characterSlot?.enabled ? plan.characterSlot : undefined} models={data.models} loras={overrides.loras || []} onChange={(loras: Any[], prompt?: string) => update(item.id, { overrides: { loras, ...(prompt === undefined ? {} : { prompt }) } })} checkpointBase={modelBases(data.models.find((model: Model) => model.id === overrides.checkpointId)).join(', ')} prompt={overrides.prompt} onPromptChange={(prompt: string) => update(item.id, { overrides: { prompt } })} run={run}/><PromptBlocks recipe={overrides} models={data.models} label="任务正向提示词" inherited={plan.characterSlot?.enabled?plan.characterSlot:undefined} onChange={(patch:Any)=>update(item.id,{overrides:patch})}/><div className="field"><span>本次负向提示词</span><PromptEditor label="任务负向提示词" rows={3} value={overrides.negative || ''} onChange={negative => update(item.id, { overrides: { negative } })}/></div><Parameters choices={data.generationChoices} value={overrides.parameters} onChange={(parameters: Any) => update(item.id, { overrides: { parameters } })}/><WorkflowPicker value={overrides} files={data.workflowFiles} defaultPath={data.settings.defaultWorkflowPath} notify={notify} onChange={(patch: Any) => update(item.id, { overrides: { ...patch } })}/><p className="field-help">修改只作用于本次任务，原配方保持原有内容。</p></div> : <Empty icon={SlidersHorizontal} title="选择一个任务" text="点击画布中的卡片，编辑本次使用的模型与参数。"/>}{item && <footer className="inspector-save-bar"><div>{planAutosaver.status==='error'?<strong role="alert">{planAutosaver.error||'保存失败，请重试'}</strong>:<small>仅保存本次任务设置，原配方保持不变。</small>}</div><Button icon={Save} onClick={() => void saveTask()}>立即保存</Button></footer>}</aside></div><ExecutionBar data={data} plan={plan} run={run} busy={busy} afterStart={openOutputs}/></>;
}

function Settings({ data, run, busy, notify }: any) {
  const [settings, setSettings] = useState<Any>(() => structuredClone(data.settings)); const [key, setKey] = useState('');
  return <><div className="page-title"><div><div className="eyebrow">MAKE THIS SPACE YOURS</div><h1>偏好设置<span className="title-dot">.</span></h1><p>管理模型来源、目录与生成偏好。</p></div><Button icon={Save} className="primary" disabled={busy.includes('settings')} onClick={async()=>{const saved=await run('settings',()=>api('settings:update',settings),'路径与来源设置已保存');if(saved)setSettings(saved);}}>保存设置</Button></div><div className="settings-grid"><AppearanceSettings notify={notify}/><section className="settings-card"><div className="settings-card-title"><span className="settings-symbol"><Download size={20}/></span><div><h3>下载加速</h3><p>模型分段并发 · 暂停后可续传</p></div></div><label className="field"><span>单个模型并发连接数</span><Select aria-label="下载并发连接数" value={settings.downloadConnections ?? 4} onChange={event => setSettings({ ...settings, downloadConnections: Number(event.target.value) })}>{[1,2,4,8].map(count => <option key={count} value={count}>{count === 1 ? '1 路 · 单连接' : `${count} 路 · 并发分段${count === 4 ? '（默认）' : ''}`}</option>)}</Select></label><p className="field-help">保存设置后用于下一次下载或续传。16 MB 以上模型默认并发下载；小文件和不支持分段的服务器使用单连接。下载完成后校验 SHA256。</p></section><ComfyConnection settings={settings} onChange={setSettings} connection={data.connection} run={run} busy={busy} notify={notify}/><section className="settings-card"><div className="settings-card-title"><span className="settings-symbol"><KeyRound size={20}/></span><div><h3>Civitai 连接</h3><p>密钥仅由桌面工具保存和使用</p></div><Badge tone={data.keyConfigured ? 'mint' : ''}>{data.keyConfigured ? '已配置' : '待配置'}</Badge></div><label className="field"><span>默认模型来源</span><Select aria-label="默认模型来源" value={settings.sourceOrigin} onChange={e => setSettings({ ...settings, sourceOrigin: e.target.value })}><option value="https://civitai.red">civitai.red</option><option value="https://civitai.com">civitai.com</option></Select></label><label className="field"><span>API Key</span><input type="password" autoComplete="off" placeholder={data.keyConfigured ? '已加密保存；输入新密钥可替换' : '粘贴你的 Civitai API Key'} value={key} onChange={e => setKey(e.target.value)}/></label><div className="settings-inline-actions"><Button icon={ShieldCheck} disabled={!key || busy.includes('key')} onClick={async () => { const saved = await run('key', () => api('key:save', { origin: settings.sourceOrigin, key }), '密钥已加密保存'); if (saved) setKey(''); }}>保存密钥</Button><Button className="text-button" disabled={!data.keyConfigured} onClick={() => run('key', () => api('key:remove', { origin: settings.sourceOrigin }), '密钥已移除')}>移除密钥</Button></div>{data.keyError && <p className="inline-error" role="alert">{data.keyError}</p>}<p className="field-help">公开模型资料可直接读取。部分模型下载需要有效密钥及账户资源权限。</p></section>

    <section className="settings-card"><div className="settings-card-title"><span className="settings-symbol"><FolderOpen size={20}/></span><div><h3>自动化输出目录</h3><p>备选图与编号后的保留图</p></div></div><DirectoryField value={settings.automationOutputDirectory ?? data.automationOutputs?.root} onChange={(value: string) => setSettings({ ...settings, automationOutputDirectory: value })}/><p className="field-help">保存设置后用于新批次。单个配方流可在自动化编排中覆盖目录；已有结果可从对应批次打开。</p></section><section className="settings-card paths-card"><div className="settings-card-title"><span className="settings-symbol"><FolderOpen size={20}/></span><div><h3>按类型存放模型</h3><p>修改只影响新下载；不会移动已有模型文件</p></div><Badge>{Object.keys(settings.paths).length} 种类型</Badge></div><div className="path-table"><div className="path-table-head"><span>模型类型</span><span>默认存放路径</span><span/></div>{Object.entries(settings.paths).map(([type, value]) => <div className="path-table-row" key={type}><span><span className="tiny-dot"/>{typeLabel(type)}</span><input aria-label={`${type} 默认路径`} value={String(value)} onChange={e => setSettings({ ...settings, paths: { ...settings.paths, [type]: e.target.value } })}/><IconButton icon={FolderOpen} label={`选择 ${type} 目录`} onClick={async () => { const selected = await api('choose-directory', { path: value }); if (selected) setSettings((s: Any) => ({ ...s, paths: { ...s.paths, [type]: selected } })); }}/></div>)}</div><p className="field-help">外部目录可用于管理和下载。ComfyUI 是否加载该目录需在后续工作流接入时单独配置；当前不会改写原整合包配置。</p></section>
    <section className="settings-card"><div className="settings-card-title"><span className="settings-symbol lavender"><FileJson size={20}/></span><div><h3>备份与恢复</h3><p>保存配方、编排与模型资料索引</p></div></div><div className="settings-inline-actions"><Button icon={FileDown} onClick={() => run('backup', () => api('backup:export'), '备份导出操作完成')}>导出备份</Button><Button icon={FileUp} onClick={() => run('backup', () => api('backup:import'), '备份导入操作完成')}>导入备份</Button></div><p className="field-help">备份不包含模型权重、封面文件或密钥。模型原始资料与说明保存在模型文件旁的 .cms 文件夹中。</p></section><section className="settings-card"><div className="settings-card-title"><span className="settings-symbol"><Monitor size={20}/></span><div><h3>关于这个空间</h3><p>模序 · Comfy Model Studio {data.version}</p></div></div><div className="info-block"><label>应用数据目录</label><code>{data.dataDir}</code></div><p className="field-help">当前版本提供模型管理、下载采集、配方、编排与本地 ComfyUI 执行。生成结果和实际工作流快照保存在应用数据目录。</p></section></div></>;
}

createRoot(document.getElementById('root')!).render(<App/>);
